// Valida y normaliza la query entrante
const body = $input.item.json.body || $input.item.json;
const query = (body.query || '').trim();
const topK = body.top_k || 3;
const categoria = body.categoria || null;

if (!query) {
  throw new Error('El campo "query" es obligatorio');
}

return { query, top_k: topK, categoria };

// Construye el SQL de busqueda semantica sobre las 3 tablas de la KB
// (kb_servicios + kb_faq + kb_politicas), con el embedding inline.
const params = $('Validar query').item.json;
const embeddingResp = $input.item.json;
const embedding = embeddingResp.data?.[0]?.embedding;

if (!embedding) {
  throw new Error('No se pudo generar embedding de la query');
}

function escString(s) {
  if (s === null || s === undefined) return 'NULL';
  return "'" + String(s).replace(/'/g, "''") + "'";
}

const E = "'[" + embedding.join(',') + "]'::vector";
const topK = parseInt(params.top_k, 10) || 3;
const catServ = params.categoria ? `WHERE categoria = ${escString(params.categoria)}` : '';

const sql = `
(SELECT 'servicio' AS tipo, id, slug, categoria, nombre, descripcion_corta, descripcion_larga,
        precio_setup, precio_recurrente, tiempo_entrega, entregables, casos_uso, prerequisitos,
        NULL::text AS pregunta, NULL::text AS respuesta, NULL::text AS topic, NULL::text AS contenido,
        1 - (embedding <=> ${E}) AS similarity
   FROM kb_servicios ${catServ}
   ORDER BY embedding <=> ${E} LIMIT ${topK})
UNION ALL
(SELECT 'faq' AS tipo, id, NULL::text AS slug, categoria, NULL::text AS nombre, NULL::text AS descripcion_corta,
        NULL::text AS descripcion_larga, NULL::text AS precio_setup, NULL::text AS precio_recurrente,
        NULL::text AS tiempo_entrega, NULL::text[] AS entregables, NULL::text[] AS casos_uso,
        NULL::text[] AS prerequisitos, pregunta, respuesta, NULL::text AS topic, NULL::text AS contenido,
        1 - (embedding <=> ${E}) AS similarity
   FROM kb_faq
   ORDER BY embedding <=> ${E} LIMIT 3)
UNION ALL
(SELECT 'politica' AS tipo, id, NULL::text AS slug, NULL::text AS categoria, NULL::text AS nombre,
        NULL::text AS descripcion_corta, NULL::text AS descripcion_larga, NULL::text AS precio_setup,
        NULL::text AS precio_recurrente, NULL::text AS tiempo_entrega, NULL::text[] AS entregables,
        NULL::text[] AS casos_uso, NULL::text[] AS prerequisitos, NULL::text AS pregunta,
        NULL::text AS respuesta, topic, contenido,
        1 - (embedding <=> ${E}) AS similarity
   FROM kb_politicas
   ORDER BY embedding <=> ${E} LIMIT 2)
ORDER BY similarity DESC;`;

return { sql, query: params.query };

// Separa las filas del UNION por tipo. Mantiene `resultados` = servicios (shape
// original, para no romper el Conversational) y agrega `faq` y `politicas`.
const items = $input.all();
const query = $('Validar query').item.json.query;
const all = items.map(it => it.json).filter(r => r && r.tipo);

const resultados = all.filter(r => r.tipo === 'servicio').map(r => ({
  id: r.id, slug: r.slug, categoria: r.categoria, nombre: r.nombre,
  descripcion_corta: r.descripcion_corta, descripcion_larga: r.descripcion_larga,
  precio_setup: r.precio_setup, precio_recurrente: r.precio_recurrente,
  tiempo_entrega: r.tiempo_entrega, entregables: r.entregables,
  casos_uso: r.casos_uso, prerequisitos: r.prerequisitos, similarity: r.similarity
}));

const faq = all.filter(r => r.tipo === 'faq').map(r => ({
  id: r.id, categoria: r.categoria, pregunta: r.pregunta, respuesta: r.respuesta, similarity: r.similarity
}));

const politicas = all.filter(r => r.tipo === 'politica').map(r => ({
  id: r.id, topic: r.topic, contenido: r.contenido, similarity: r.similarity
}));

return { ok: true, query, total: resultados.length, resultados, faq, politicas };

